using System;using System.IO;using System.IO.Pipes;using System.Text;using System.Threading;using System.Diagnostics;using System.Xml.Serialization;using AutoCat.Diagnostics;
public class Settings {
 public int Taps=10,MenuKey=45,PauseKey=36,MenuModifiers,PauseModifiers;
 public bool Clicker,Gifts,Exchange,Emoting,InstaGift,ExtremeRates; public int EmoteRate=10;
 public void Validate(){EmoteRate=Math.Max(1,Math.Min(ExtremeRates?RatePolicy.EmoteMaximum:RatePolicy.NormalEmoteMaximum,EmoteRate));Taps=Math.Max(1,Math.Min(ExtremeRates?TapEngine.MaximumRate:RatePolicy.NormalClickMaximum,Taps));if(MenuKey<0||MenuKey>259)MenuKey=45;if(PauseKey<0||PauseKey>259)PauseKey=36;MenuModifiers&=15;PauseModifiers&=15;}
 public static Settings Read(string path){try{using(var f=File.OpenRead(path)){var s=(Settings)new XmlSerializer(typeof(Settings)).Deserialize(f);int oldTaps=s.Taps,oldEmotes=s.EmoteRate;s.Validate();Diag.Values(LogLevel.Info,"Settings","loaded","source=settings.xml taps={0} emoteRate={1} priorTaps={2} priorEmoteRate={3}",s.Taps,s.EmoteRate,oldTaps,oldEmotes);return s;}}catch(FileNotFoundException){Diag.Write(LogLevel.Info,"Settings","defaults","No saved configuration");return new Settings();}catch(DirectoryNotFoundException){Diag.Write(LogLevel.Info,"Settings","defaults","No saved configuration directory");return new Settings();}catch(Exception e){Diag.Fault("Settings","load.failed.defaults",e);return new Settings();}}
 public void Save(string path){var safe=(Settings)MemberwiseClone();safe.Validate();Diag.Values(LogLevel.Info,"Settings","save.requested","source=settings.xml taps={0} emoteRate={1} extreme={2}",safe.Taps,safe.EmoteRate,safe.ExtremeRates?1:0);long start=Stopwatch.GetTimestamp();try{Directory.CreateDirectory(Path.GetDirectoryName(path));string temp=path+".tmp";using(var f=File.Create(temp))new XmlSerializer(typeof(Settings)).Serialize(f,safe);if(File.Exists(path))File.Replace(temp,path,null);else File.Move(temp,path);}catch(Exception e){Diag.Fault("Settings","save.failed",e);throw;}
  if(Diag.Current!=null)try{Settings read;using(var f=File.OpenRead(path))read=(Settings)new XmlSerializer(typeof(Settings)).Deserialize(f);bool equal=true;foreach(var field in typeof(Settings).GetFields())if(!Object.Equals(field.GetValue(safe),field.GetValue(read)))equal=false;Diag.Values(equal?LogLevel.Info:LogLevel.Error,"Settings",equal?"save.verified":"save.verification.failed","source=settings.xml elapsedMs={0}",(Stopwatch.GetTimestamp()-start)*1000/Stopwatch.Frequency);}catch(Exception e){Diag.Fault("Settings","readback.failed",e);}
 }
}
// Only confirmed permission is saved; a pending confirmation never grants access.
sealed class RatePolicy {
 public const int NormalClickMaximum=200,NormalEmoteMaximum=100,EmoteMaximum=100000000;
 public bool Enabled{get;private set;}public bool Pending{get;private set;}
 public void Restore(bool confirmed){Enabled=confirmed;Pending=false;}
 public void Request(bool value){if(!value){Enabled=false;Pending=false;}else if(!Enabled)Pending=true;}
 public void Confirm(){if(Pending){Enabled=true;Pending=false;}}
 public int Clamp(int rate,bool emote){return Math.Max(1,Math.Min(Enabled?(emote?EmoteMaximum:TapEngine.MaximumRate):(emote?NormalEmoteMaximum:NormalClickMaximum),rate));}
}
sealed class TapEngine:IDisposable {
 public const int MaximumRate=100000000;public const long CounterCeiling=2000000000;
 readonly string pipeName;readonly object gate=new object();Thread worker;NamedPipeServerStream pipe;volatile bool closed;
 public volatile float PerformanceScale=1;public volatile bool Enabled;public volatile int Rate=1000;public volatile string Status="waiting";public long Sent;
 long remaining;long observed;bool initialized;int wake;string loggedStatus="";long lastSummary,lastSent;
 public TapEngine(string name="BongoCatxTheFarmerWasReplaced"){pipeName=name;}
 public long Remaining {get{lock(gate)return remaining;}}
 public void QueueWakeup(){Interlocked.Exchange(ref wake,1);}
 public void Observe(int total,int lifetime){lock(gate){if(total<0||lifetime<0){initialized=false;return;}long allowed=Math.Max(0,CounterCeiling-Math.Max(total,lifetime));remaining=initialized?Math.Min(remaining,allowed):allowed;initialized=true;observed=Stopwatch.GetTimestamp();}}
 public void ResetGuard(){lock(gate){initialized=false;remaining=0;}}
 public static int Grant(int requested,long budget){return (int)Math.Max(0,Math.Min(Math.Max(0,requested),budget));}
 public void Start(){if(worker!=null)return;Diag.Write(LogLevel.Info,"Clicks","transport.start","batched intervalMs=100; no individual tap logging");worker=new Thread(Run);worker.IsBackground=true;worker.Start();}
 static readonly byte[] ZeroFrame=Frame("0");
 public static byte[] Frame(string s){var b=Encoding.Unicode.GetBytes(s);var a=new byte[b.Length+2];a[0]=(byte)(b.Length>>8);a[1]=(byte)b.Length;Buffer.BlockCopy(b,0,a,2,b.Length);return a;}
 void Run(){while(!closed){try{using(var p=new NamedPipeServerStream(pipeName,PipeDirection.InOut,1,PipeTransmissionMode.Byte,PipeOptions.Asynchronous)){
  lock(gate){if(closed)return;pipe=p;}Status="waiting for game";var wait=p.BeginWaitForConnection(null,null);using(wait.AsyncWaitHandle){while(!closed&&!wait.AsyncWaitHandle.WaitOne(200)){}if(closed)return;p.EndWaitForConnection(wait);}
  var timer=Stopwatch.StartNew();long last=timer.ElapsedMilliseconds;double fraction=0;lastSummary=0;lastSent=Interlocked.Read(ref Sent);
  while(!closed&&p.IsConnected){Thread.Sleep((int)(100/Math.Max(0.2f,PerformanceScale)));long now=timer.ElapsedMilliseconds;int count=0;
   lock(gate){bool fresh=initialized&&(Stopwatch.GetTimestamp()-observed)/(double)Stopwatch.Frequency<2;
    if(Enabled&&fresh&&remaining>0){fraction+=Math.Min(0.25,(now-last)/1000.0)*Math.Max(1,Math.Min(MaximumRate,Rate))*Math.Max(0,Math.Min(1,PerformanceScale));int request=(int)fraction;count=Grant(request,remaining);fraction-=request;remaining-=count;Status="connected";}
    else{fraction=0;Status=!Enabled?"connected":!fresh?"waiting for live counter":remaining<=0?"counter cutoff reached":"paused";}
    if(Interlocked.Exchange(ref wake,0)!=0&&count==0&&(!initialized||remaining>0)){count=1;if(initialized)remaining--;}
   }
   if(Status!=loggedStatus){loggedStatus=Status;Diag.Write(LogLevel.Info,"Clicks","transport.state",Status);}if(now-lastSummary>=30000){long sent=Interlocked.Read(ref Sent);Diag.Values(LogLevel.Info,"Clicks","summary","windowMs={0} sentDelta={1} sentTotal={2} requestedRate={3}",now-lastSummary,sent-lastSent,sent,Rate);lastSummary=now;lastSent=sent;}if(Diag.Enabled(LogLevel.Trace)&&count>0&&now%1000<110)Diag.Values(LogLevel.Trace,"Clicks","batch.sample","batchCount={0}",count);
   last=now;var frame=count==0?ZeroFrame:Frame(count.ToString(System.Globalization.CultureInfo.InvariantCulture));var write=p.BeginWrite(frame,0,frame.Length,null,null);
   using(write.AsyncWaitHandle){if(!write.AsyncWaitHandle.WaitOne(1000))throw new IOException("Tap connection timed out");p.EndWrite(write);}Interlocked.Add(ref Sent,count);
  }
 }}catch(Exception e){if(!closed){if(BridgeClient.PipeDisconnected(e)){Status="waiting for game";Diag.CurrentLimited("Clicks","transport.disconnected","Game tap connection closed; waiting to reconnect");}else{Status=e.Message;Diag.Fault("Clicks","transport.failed",e);}}}finally{lock(gate){pipe=null;}}if(!closed)Thread.Sleep(750);}}
 public void Dispose(){closed=true;Enabled=false;lock(gate){if(pipe!=null)pipe.Dispose();}bool drained=worker==null||worker.Join(1500);Diag.Values(drained?LogLevel.Info:LogLevel.Warn,"Clicks","transport.stop","threadJoined={0} sentTotal={1}",drained?1:0,Interlocked.Read(ref Sent));}
}
sealed class GameState {
 public long NormalTokens=-1,EmoteTokens=-1;public float PerformanceScale=1;public double FrameMs,PeakMs,EmoteBudget;public int EmoteTotal=-1,EmoteCalls;public bool Ready;public int Total,Lifetime,Spent,NormalTimer,EmoteTimer,Possible,Claims,Exchanges;public bool NormalReady,EmoteReady;public string Message="waiting for game";public DateTime At=DateTime.UtcNow;
 public static GameState Parse(string line){var s=new GameState();if(line==null)return s;var p=line.Split('|');if(p.Length>=12&&p[0]=="OK"){
  s.Total=int.Parse(p[1]);s.Lifetime=int.Parse(p[2]);s.Spent=int.Parse(p[3]);s.NormalReady=p[4]=="1";s.EmoteReady=p[5]=="1";s.NormalTimer=int.Parse(p[6]);s.EmoteTimer=int.Parse(p[7]);s.Possible=int.Parse(p[8]);s.Claims=int.Parse(p[9]);s.Exchanges=int.Parse(p[10]);s.Message=Encoding.UTF8.GetString(Convert.FromBase64String(p[11]));if(p.Length>=14){s.EmoteTotal=int.Parse(p[12]);s.EmoteCalls=int.Parse(p[13]);}if(p.Length>=18){s.PerformanceScale=float.Parse(p[14],System.Globalization.CultureInfo.InvariantCulture);s.FrameMs=double.Parse(p[15],System.Globalization.CultureInfo.InvariantCulture);s.PeakMs=double.Parse(p[16],System.Globalization.CultureInfo.InvariantCulture);s.EmoteBudget=double.Parse(p[17],System.Globalization.CultureInfo.InvariantCulture);}if(p.Length>=20){s.NormalTokens=long.Parse(p[18]);s.EmoteTokens=long.Parse(p[19]);}s.Ready=s.Total>=0&&s.Lifetime>=0;
 }else if(p.Length>1&&p[0]=="ERROR")s.Message=Encoding.UTF8.GetString(Convert.FromBase64String(p[1]));return s;}
}
sealed class BridgeClient:IDisposable {
 readonly string dll;readonly TapEngine taps;Thread worker;volatile bool closed;NamedPipeClientStream pipe;readonly object gate=new object();
 public volatile string CosmeticCatalog="";public volatile bool CatalogRequested;int previewPending=int.MinValue;public void PreviewCosmetic(int id){Interlocked.Exchange(ref previewPending,id);}public volatile bool UnlockAll;public volatile bool Running,Gifts,Exchange,Emoting,InstaGift;public volatile int EmoteRate=1;public volatile GameState State=new GameState();public volatile string Connection="waiting for game";
