 public void Start(){worker=new Thread(Loop);worker.IsBackground=true;worker.Start();}
 static string ReadLineBounded(StreamReader reader){var task=reader.ReadLineAsync();if(!task.Wait(2500))throw new IOException("Bridge response timed out");return task.Result;}
 static void LogState(GameState next,ref GameState prior,ref long summary){long now=Stopwatch.GetTimestamp();if(prior==null||prior.Ready!=next.Ready)Diag.Write(LogLevel.Info,"State",next.Ready?"ready":"unavailable","source=game-component observation; persistence unverified");if(next.Ready){if(prior==null||!prior.Ready||next.Lifetime<prior.Lifetime)Diag.Values(prior==null||!prior.Ready?LogLevel.Info:LogLevel.Warn,"LifetimeTaps",prior==null||!prior.Ready?"observed":"decreased","source=process-memory prior={0} observed={1}; no reset performed by diagnostics",prior==null||!prior.Ready?-1:prior.Lifetime,next.Lifetime);
   if(prior==null||prior.NormalTokens!=next.NormalTokens||prior.EmoteTokens!=next.EmoteTokens)Diag.Values(LogLevel.Info,"Gifts","tokens.observed","source=Steam-inventory-cache normalBefore={0} normalAfter={1} emoteBefore={2} emoteAfter={3}",prior==null?-1:prior.NormalTokens,next.NormalTokens,prior==null?-1:prior.EmoteTokens,next.EmoteTokens);
   if(prior==null||prior.Message!=next.Message)Diag.Write(String.IsNullOrEmpty(next.Message)?LogLevel.Info:LogLevel.Warn,"State",String.IsNullOrEmpty(next.Message)?"condition.cleared":"condition",next.Message);
   if(now-summary>=30*Stopwatch.Frequency){Diag.Values(LogLevel.Info,"State","summary","source=process-memory lifetime={0} gained={1} spent={2} emotesCached={3}",next.Lifetime,next.Total,next.Spent,next.EmoteTotal);Diag.Values(LogLevel.Info,"Performance","summary","frameAvgUs={0} framePeakUs={1} tapScalePermille={2} emoteBudget={3}",(long)(next.FrameMs*1000),(long)(next.PeakMs*1000),(long)(next.PerformanceScale*1000),(long)next.EmoteBudget);summary=now;}
  }prior=next;}
 internal static bool StartupNotReady(Exception error){string message=(error.InnerException??error).Message;return message.IndexOf("Input hook not initialized",StringComparison.OrdinalIgnoreCase)>=0||message.IndexOf("Bongo Cat not initialized",StringComparison.OrdinalIgnoreCase)>=0;}
 internal static bool PipeDisconnected(Exception error){var root=error.InnerException??error;if(!(root is IOException))return false;string message=root.Message;return message.IndexOf("pipe is broken",StringComparison.OrdinalIgnoreCase)>=0||message.IndexOf("pipe has been ended",StringComparison.OrdinalIgnoreCase)>=0||message.IndexOf("pipe is closed",StringComparison.OrdinalIgnoreCase)>=0||message.IndexOf("pipe has not been connected",StringComparison.OrdinalIgnoreCase)>=0;}
 void Loop(){int lastPid=0,observedPid=0;bool loaded=false,searchLogged=false;long samePidReloadAfter=0;GameState previous=null;long summaryAt=0;Diag.Write(LogLevel.Info,"Connection","polling.start","controlIntervalMs=100; processSearchMs=750");while(!closed){try{
  int pid=0;foreach(var p in Process.GetProcessesByName("BongoCat")){using(p){pid=p.Id;break;}}if(pid==0){if(!searchLogged){Diag.Values(LogLevel.Info,"Connection",lastPid==0?"searching":"process.disappeared","previousPid={0}",lastPid);searchLogged=true;}Connection="waiting for game";State=new GameState();taps.ResetGuard();lastPid=0;loaded=false;Thread.Sleep(750);continue;}
  searchLogged=false;if(pid!=lastPid){if(observedPid!=0&&observedPid!=pid)Diag.Values(LogLevel.Info,"Connection","game.restart.detected","previousPid={0} pid={1}; counter persistence not inferred",observedPid,pid);observedPid=pid;Diag.Values(LogLevel.Info,"Connection",lastPid==0?"process.found":"process.changed","pid={0} previousPid={1}",pid,lastPid);try{using(var target=Process.GetProcessById(pid)){var module=target.MainModule;string version=module==null?"":module.FileVersionInfo.FileVersion;if(String.IsNullOrEmpty(version))Diag.CurrentLimited("Connection","metadata.pending","Executable metadata is not ready; attachment will continue");else Diag.Write(LogLevel.Info,"Connection","game.metadata","fileVersion="+version+" source=executable-metadata");}}catch(Exception){var log=Diag.Current;if(log!=null)log.Limited(LogLevel.Warn,"Connection","metadata.unavailable","Executable metadata unavailable; attachment will continue");}loaded=false;lastPid=pid;taps.ResetGuard();previous=null;}
  using(var p=new NamedPipeClientStream(".","autocat-control-"+pid,PipeDirection.InOut,PipeOptions.Asynchronous)){
   lock(gate){if(closed)return;pipe=p;}
   try{p.Connect(200);}catch(TimeoutException){bool existing=loaded;if(!loaded){Connection="attaching";Diag.Values(LogLevel.Info,"Connection","attach.attempt","pid={0} method=Mono",pid);BridgeLoader.Load(pid,dll);loaded=true;taps.QueueWakeup();}else Diag.CurrentLimited("Connection","reconnect.wait","Waiting for existing component; same PID");try{p.Connect(6000);}catch(TimeoutException){if(!existing)throw;long now=Stopwatch.GetTimestamp();if(now>=samePidReloadAfter){loaded=false;samePidReloadAfter=now+10*Stopwatch.Frequency;Diag.Write(LogLevel.Warn,"Connection","same_pid.reinject","Component pipe remained unavailable; scheduling one bounded reinjection");}Connection="waiting for component";State=new GameState{Message=Connection};taps.ResetGuard();taps.PerformanceScale=0;Thread.Sleep(250);continue;}}
   Connection="attached";samePidReloadAfter=0;Diag.Values(LogLevel.Info,"Connection","attached","pid={0}",pid);using(var reader=new StreamReader(p,Encoding.UTF8,false,1024,true))using(var writer=new StreamWriter(p,new UTF8Encoding(false),1024,true)){writer.AutoFlush=true;
    if(Diag.Current!=null){writer.WriteLine(DiagnosticSession.Handshake());string response=ReadLineBounded(reader);if(response!="LOGOK")Diag.Write(LogLevel.Warn,"Logger","handshake.failed","Runtime did not accept shared diagnostic session");}
    while(!closed&&p.IsConnected){if(CatalogRequested){writer.WriteLine("CATALOG");CosmeticCatalog=ReadLineBounded(reader);CatalogRequested=false;}int choice=Interlocked.Exchange(ref previewPending,int.MinValue);if(choice!=int.MinValue){writer.WriteLine("PREVIEW|"+choice);ReadLineBounded(reader);}writer.WriteLine("SET|"+(Running?"1":"0")+"|"+(Gifts?"1":"0")+"|"+(Exchange?"1":"0")+"|"+(Emoting?"1":"0")+"|"+EmoteRate+"|"+(InstaGift?"1":"0")+"|"+(UnlockAll?"1":"0"));var next=GameState.Parse(ReadLineBounded(reader));State=next;LogState(next,ref previous,ref summaryAt);taps.PerformanceScale=next.PerformanceScale;if(next.Ready)taps.Observe(next.Total,next.Lifetime);Thread.Sleep(100);}
    if(p.IsConnected){Diag.Write(LogLevel.Info,"Connection","unload.requested","Runtime cleanup requested");writer.WriteLine("UNLOAD");ReadLineBounded(reader);Diag.Write(LogLevel.Info,"Connection","unload.acknowledged","Request acknowledged; cleanup completion logged by game component");}
   }
  }
  }catch(Exception e){if(!closed){if(StartupNotReady(e)){var log=Diag.Current;if(log!=null)log.Limited(LogLevel.Warn,"Connection","startup.not_ready","Bongo Cat is still initializing; attach will retry");Connection="waiting for game initialization";}else if(PipeDisconnected(e)){var log=Diag.Current;if(log!=null)log.Limited(LogLevel.Warn,"Connection","component.disconnected","Game component connection closed; recovery will retry");Connection="waiting for component";}else{Diag.Fault("Connection","disconnected",e);Connection=e.Message;}CosmeticCatalog="";Interlocked.Exchange(ref previewPending,int.MinValue);State=new GameState{Message=Connection};taps.ResetGuard();taps.PerformanceScale=0;}}finally{lock(gate){pipe=null;}}
 if(!closed)Thread.Sleep(1000);
 }}
 public void Dispose(){Running=false;closed=true;if(worker!=null&&!worker.Join(3500)){Diag.Write(LogLevel.Warn,"Connection","shutdown.timeout","Closing unresponsive control pipe");lock(gate){if(pipe!=null)pipe.Dispose();}worker.Join(500);}Diag.Write(LogLevel.Info,"Connection","polling.stop","Client stopped");}
}
